import{_ as s,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"UB与UB数据搬运","link":"/api/SIMD-API/c_api/data_move_guide/ub_ub_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/ub_ub_data_move.md","filePath":"api/SIMD-API/c_api/data_move_guide/ub_ub_data_move.md","outlineHeaders":[{"level":2,"title":"总体说明","slug":"总体说明","link":"#总体说明"},{"level":2,"title":"连续数据搬运","slug":"连续数据搬运","link":"#连续数据搬运"},{"level":2,"title":"高维切分数据搬运","slug":"高维切分数据搬运","link":"#高维切分数据搬运"},{"level":2,"title":"地址重叠示例","slug":"地址重叠示例","link":"#地址重叠示例"},{"level":2,"title":"容量与同步","slug":"容量与同步","link":"#容量与同步"}],"lastUpdated":1790563388000}'),l={name:"api/SIMD-API/c_api/data_move_guide/ub_ub_data_move.md"};function t(e,a,d,o,_,i){return n(),p("div",null,[...a[0]||(a[0]=[c(`<div><article class="markdown-body"><h1>UB与UB数据搬运</h1><p>NPU架构版本3510通过<a href="../vector_datamove/asc_copy_ub2ub.html">asc_copy_ub2ub</a>在UB内部复制数据。接口运行在PIPE_V，仅在AIV生效，支持连续和高维切分两种模式，数据格式和内容保持不变。</p><h2 id="总体说明">总体说明<a class="header-anchor" href="#总体说明">​</a></h2><table><thead><tr><th>搬运模式</th><th>适用场景</th><th>关键参数单位</th></tr></thead><tbody><tr><td>连续</td><td>源、目的均为一段连续UB数据</td><td><code>size</code>：字节</td></tr><tr><td>高维切分</td><td>源或目的由多个等长数据块组成，块间存在固定间隔</td><td>块长、源/目的间隔：32字节DataBlock</td></tr></tbody></table><p>需要在UB中按掩码选择元素、广播或完成数据类型相关的重排时，可在Vector Function中使用Reg加载、计算和存储接口，参见<a href="reg_ub_data_move.html">Reg与UB数据搬运</a>。</p><h2 id="连续数据搬运">连续数据搬运<a class="header-anchor" href="#连续数据搬运">​</a></h2><p>连续模式从<code>src</code>开始复制<code>size</code>字节到<code>dst</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_ub2ub</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="p">)</span>
</code></pre></div><ul><li>源、目的地址均需要32字节对齐。</li><li><code>size</code>取值范围为[32, 65535×32]，并且需要是32的整数倍。</li><li><code>size</code>不对齐时，硬件按<code>size / 32</code>向下截断，尾部不足32字节的数据不会复制。</li><li>连续模式的源、目的有效范围不能重叠。</li></ul><h2 id="高维切分数据搬运">高维切分数据搬运<a class="header-anchor" href="#高维切分数据搬运">​</a></h2><p>高维切分模式搬运<code>burst_count</code>个数据块，每个数据块包含<code>burst_len</code>个DataBlock：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_ub2ub</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_count</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_len</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_gap</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">)</span>
</code></pre></div><ul><li><code>burst_len</code>以32字节DataBlock为单位。</li><li><code>src_gap</code>和<code>dst_gap</code>表示前一数据块结束地址到下一数据块起始地址的间隔，同样以DataBlock为单位。</li><li>源访问跨度为<code>(burst_count - 1) * (burst_len + src_gap) + burst_len</code>个DataBlock，目的访问跨度使用<code>dst_gap</code>按相同方式计算。</li><li>各个实际参与搬运的源DataBlock和目的DataBlock不能重叠。如果块间间隔使有效DataBlock互不相交，则源、目的整体地址跨度可以交叠。</li></ul><h2 id="地址重叠示例">地址重叠示例<a class="header-anchor" href="#地址重叠示例">​</a></h2><p>假设每个数据块长度为2个DataBlock，共搬运2块：</p><ul><li><code>src_gap=1</code>时，源端有效块为DataBlock 0、1和3、4。</li><li><code>dst_gap=2</code>时，目的端有效块为DataBlock 0、1和4、5。</li></ul><p>判断是否支持搬运时，应逐块比较源、目的有效DataBlock，而不是只比较两段整体跨度。接口不提供类似<code>memmove</code>的重叠复制语义；需要移动重叠区域时，应使用不重叠的临时UB空间分阶段处理，并在复用空间前完成同步。</p><h2 id="容量与同步">容量与同步<a class="header-anchor" href="#容量与同步">​</a></h2><ul><li>源、目的地址加实际访问跨度均不得超过已分配UB范围。UB名义容量为256KB，实际可用容量还会受SIMD VF栈、预留空间和SIMT Data Cache影响。</li><li><code>asc_copy_ub2ub</code>运行在PIPE_V。在NPU架构版本3510上，PIPE_V内部的执行顺序由硬件保证，多条<code>asc_copy_ub2ub</code>之间不需要额外插入事件同步。</li><li>目的UB随后由PIPE_MTE3或其他流水读取时，使用<a href="../sync/intra_core_sync/asc_sync_notify.html">asc_sync_notify</a>和<a href="../sync/intra_core_sync/asc_sync_wait.html">asc_sync_wait</a>建立PIPE_V到消费者流水的依赖。</li></ul></article></div>`,1)])])}const u=s(l,[["render",t]]);export{h as __pageData,u as default};
